css:
.trading-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #f0f2f5 0%, #e8ecf1 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.trading-sim-container .trading-sim-header {
    background: linear-gradient(135deg, #1a2332 0%, #2c3e50 100%);
    color: white;
    padding: 30px;
    border-radius: 15px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(0,0,0,0.25);
    text-align: center;
}

.trading-sim-container .trading-sim-header-icon {
    font-size: 2.5rem;
    margin-bottom: 8px;
}

.trading-sim-container .trading-sim-header h1 {
    color: #c8a951;
    margin-bottom: 5px;
    font-size: 1.8rem;
}

.trading-sim-container .trading-sim-header p {
    color: #b0bec5;
    margin: 0;
    font-size: 1rem;
}

.trading-sim-container .trading-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 20px;
    font-weight: 600;
}

.trading-sim-container .trading-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}

.trading-sim-container .trading-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 20px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.2s ease;
}

.trading-sim-container .trading-sim-status-card:hover {
    transform: translateY(-3px);
}

.trading-sim-container .trading-sim-label {
    color: #888;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.trading-sim-container .trading-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #1a2332;
}

.trading-sim-container .trading-sim-briefing {
    background: white;
    border-left: 4px solid #2980b9;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.trading-sim-container .trading-sim-briefing h3 {
    color: #2980b9;
    margin-bottom: 12px;
    font-size: 1.1rem;
}

.trading-sim-container .trading-sim-bias-panel {
    background: #fff8e1;
    border-left: 4px solid #f39c12;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.trading-sim-container .trading-sim-bias-panel h4 {
    color: #e67e22;
    margin-bottom: 10px;
    font-size: 1rem;
}

.trading-sim-container .trading-sim-bias-panel select {
    margin-top: 12px;
    max-width: 600px;
}

.trading-sim-container .trading-sim-controls {
    background: white;
    border-radius: 12px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.trading-sim-container .trading-sim-controls h3 {
    color: #1a2332;
    margin-bottom: 5px;
}

.trading-sim-container .trading-sim-hint {
    color: #888;
    font-size: 0.9rem;
    margin-bottom: 18px;
}

.trading-sim-container .trading-sim-allocation-grid {
    display: grid;
    gap: 14px;
    margin-bottom: 18px;
}

.trading-sim-container .trading-sim-alloc-row {
    display: grid;
    grid-template-columns: 220px 100px 1fr;
    align-items: center;
    gap: 12px;
}

.trading-sim-container .trading-sim-alloc-row label {
    font-weight: 600;
    color: #333;
    font-size: 0.9rem;
}

.trading-sim-container .trading-sim-alloc-row input {
    width: 100px;
    text-align: center;
}

.trading-sim-container .trading-sim-asset-detail {
    color: #999;
    font-size: 0.78rem;
}

.trading-sim-container .trading-sim-total {
    font-size: 1.2rem;
    font-weight: 700;
    text-align: center;
    padding: 10px;
    border-radius: 8px;
    margin-bottom: 15px;
    background: #f8f9fa;
}

.trading-sim-container .trading-sim-ips-warnings {
    margin-bottom: 12px;
}

.trading-sim-container .trading-sim-chart {
    background: white;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    height: 320px;
}

.trading-sim-container .trading-sim-history {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

@media (max-width: 768px) {
    .trading-sim-container .trading-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .trading-sim-container .trading-sim-alloc-row {
        grid-template-columns: 1fr;
    }
    .trading-sim-container .trading-sim-alloc-row input {
        width: 100%;
    }
}

