(function() {
    'use strict';

    class TradingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Sala de Operaciones';
            this.version = '1.1.0';

            this.ASSET_IDS = ['allocEquityCL', 'allocEquityUS', 'allocFixedIncome', 'allocReits', 'allocCash'];

            this.ROUND_RETURNS = [
                { equityCL: 0.042, equityUS: 0.028, fixedIncome: 0.015, reits: 0.022, cash: 0.012 },
                { equityCL: -0.058, equityUS: 0.018, fixedIncome: 0.016, reits: -0.012, cash: 0.012 },
                { equityCL: 0.035, equityUS: 0.032, fixedIncome: 0.014, reits: 0.025, cash: 0.012 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    portfolioValue: 4800,
                    portfolioHistory: [],
                    returnHistory: [],
                    sharpeRatio: 0,
                    biasScore: 100,
                    biasEvents: [],
                    ipsViolations: 0,
                    cumulativeReturn: 0,
                    benchmarkValue: 4800,
                    benchmarkHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    allocEquityCL: 25,
                    allocEquityUS: 15,
                    allocFixedIncome: 25,
                    allocReits: 15,
                    allocCash: 20,
                    biasResponse: 'none'
                };
            }

            var self = this;
            this.ASSET_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        self._updateAllocTotal();
                    });
                }
            });

            this._updateBriefing(state);
            this._updateAllocTotal();
        }

        _updateAllocTotal() {
            var total = 0;
            this.ASSET_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) total += parseInt(el.value) || 0;
            });
            var totalEl = document.getElementById('allocTotal');
            if (totalEl) totalEl.textContent = total;
            var totalDisplay = document.getElementById('allocTotalDisplay');
            if (totalDisplay) {
                totalDisplay.style.color = total === 100 ? '#27ae60' : '#e74c3c';
            }

            var warnings = [];
            var cashEl = document.getElementById('allocCash');
            var cashVal = cashEl ? parseInt(cashEl.value) || 0 : 0;
            if (cashVal < 10) {
                var t = window.mySimulation ? window.mySimulation.t('warning_cash_min') : 'Minimum 10% cash required by IPS';
                warnings.push(t);
            }
            var usEl = document.getElementById('allocEquityUS');
            var usVal = usEl ? parseInt(usEl.value) || 0 : 0;
            if (usVal > 50) {
                var t2 = window.mySimulation ? window.mySimulation.t('warning_clp_min') : 'Minimum 50% CLP-denominated assets required by IPS';
                warnings.push(t2);
            }
            var warningsEl = document.getElementById('ipsWarnings');
            if (warningsEl) {
                warningsEl.innerHTML = warnings.map(function(w) {
                    return '<div class="alert alert-warning py-1 px-2 mb-1" style="font-size:0.85rem;">' + w + '</div>';
                }).join('');
            }
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 2);

            var briefKeys = ['r1_briefing', 'r2_briefing', 'r3_briefing'];
            var biasKeys = ['r1_bias_prompt', 'r2_bias_prompt', 'r3_bias_prompt'];
            var optAKeys = ['r1_bias_optA', 'r2_bias_optA', 'r3_bias_optA'];
            var optBKeys = ['r1_bias_optB', 'r2_bias_optB', 'r3_bias_optB'];

            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(briefKeys[idx]);

            var biasEl = document.getElementById('biasPromptText');
            if (biasEl) biasEl.innerHTML = t(biasKeys[idx]);

            var optAEl = document.getElementById('biasOptionA');
            if (optAEl) optAEl.textContent = t(optAKeys[idx]);

            var optBEl = document.getElementById('biasOptionB');
            if (optBEl) optBEl.textContent = t(optBKeys[idx]);

            var biasSelect = document.getElementById('biasResponse');
            if (biasSelect) biasSelect.value = 'none';
        }

        validateDecisions(decisions) {
            var self = this;
            this.ASSET_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) decisions[id] = parseInt(el.value) || 0;
            });

            var biasEl = document.getElementById('biasResponse');
            if (biasEl) decisions.biasResponse = biasEl.value;

            var total = 0;
            this.ASSET_IDS.forEach(function(id) {
                total += decisions[id];
            });

            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_sum_100'), 'warning'
                );
                return false;
            }

            if (decisions.allocCash < 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_cash_min'), 'warning'
                );
            }

            var clpPct = decisions.allocEquityCL + decisions.allocFixedIncome + decisions.allocReits + decisions.allocCash;
            if (clpPct < 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_clp_min'), 'warning'
                );
            }

            if (decisions.biasResponse === 'none') {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_bias_response'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min(state.currentPeriod - 1, 2);
            var returns = this.ROUND_RETURNS[idx];

            var portfolioReturn =
                (d.allocEquityCL / 100) * returns.equityCL +
                (d.allocEquityUS / 100) * returns.equityUS +
                (d.allocFixedIncome / 100) * returns.fixedIncome +
                (d.allocReits / 100) * returns.reits +
                (d.allocCash / 100) * returns.cash;

            var prevValue = state.domainState.portfolioValue;
            var newValue = Math.round(prevValue * (1 + portfolioReturn));

            var violations = 0;
            if (d.allocCash < 10) violations++;
            var clpPct = d.allocEquityCL + d.allocFixedIncome + d.allocReits + d.allocCash;
            if (clpPct < 50) violations++;

            var biasCost = 0;
            var biasResult = 'rational';
            if (d.biasResponse === 'optionA') {
                biasCost = 15;
                biasResult = 'biased';
            }

            state.domainState.portfolioValue = newValue;
            state.domainState.returnHistory.push(Math.round(portfolioReturn * 10000) / 100);
            state.domainState.portfolioHistory.push(newValue);
            state.domainState.ipsViolations += violations;
            state.domainState.biasScore = Math.max(0, state.domainState.biasScore - biasCost);
            state.domainState.biasEvents.push(biasResult);
            state.domainState.cumulativeReturn = Math.round(((newValue / 4800) - 1) * 10000) / 100;

            var rHistory = state.domainState.returnHistory;
            var avgR = rHistory.reduce(function(s, r) { return s + r; }, 0) / rHistory.length;
            var rfQ = 1.45;
            var variance = rHistory.reduce(function(s, r) { return s + Math.pow(r - avgR, 2); }, 0) / rHistory.length;
            var stdDev = Math.sqrt(variance);
            if (stdDev < 0.01) stdDev = 0.01;
            var sharpe = Math.round(((avgR - rfQ) / stdDev) * 100) / 100;
            state.domainState.sharpeRatio = sharpe;

            var benchReturn = returns.equityCL + 0.0075;
            var newBench = Math.round(state.domainState.benchmarkValue * (1 + benchReturn));
            state.domainState.benchmarkValue = newBench;
            state.domainState.benchmarkHistory.push(newBench);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                quarterlyReturn: Math.round(portfolioReturn * 10000) / 100,
                portfolioValue: newValue,
                cumulativeReturn: state.domainState.cumulativeReturn,
                sharpeRatio: sharpe,
                violations: violations,
                biasResult: biasResult,
                biasScore: state.domainState.biasScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('portfolioValueDisplay', 'domainState.portfolioValue',
                function(v) { return 'CLP ' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('quarterlyReturnDisplay', 'results.quarterlyReturn',
                function(v) { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; });
            uiManager.bind('cumulativeReturnDisplay', 'domainState.cumulativeReturn',
                function(v) { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; });
            uiManager.bind('sharpeDisplay', 'domainState.sharpeRatio',
                function(v) { return v.toFixed(2); });
            uiManager.bind('biasScoreDisplay', 'domainState.biasScore');
            uiManager.bind('ipsDisplay', 'domainState.ipsViolations');
        }

        getChartConfig() {
            return {
                portfolioChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._t('chart_portfolio_label'),
                                data: [],
                                borderColor: '#1a2332',
                                backgroundColor: 'rgba(26,35,50,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3,
                                pointRadius: 6,
                                pointBackgroundColor: '#c8a951'
                            },
                            {
                                label: this._t('chart_benchmark_label'),
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.05)',
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.3,
                                pointRadius: 4,
                                pointBackgroundColor: '#e74c3c'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_title') }
                        },
                        scales: {
                            y: { beginAtZero: false }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.portfolioHistory.map(function(_, i) {
                return 'Q' + (i + 1);
            });
            return {
                portfolioChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.portfolioHistory },
                        { data: state.domainState.benchmarkHistory }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.quarterlyReturn', label: 'Return (%)', i18nKey: 'col_return',
                    formatter: function(v) { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; } },
                { key: 'results.portfolioValue', label: 'Value (CLP M)', i18nKey: 'col_value',
                    formatter: function(v) { return 'CLP ' + v.toLocaleString() + 'M'; } },
                { key: 'results.sharpeRatio', label: 'Sharpe', i18nKey: 'col_sharpe',
                    formatter: function(v) { return v.toFixed(2); } },
                { key: 'results.biasScore', label: 'Bias Score', i18nKey: 'col_bias' }
            ];
        }

        getHint(state, results) {
            if (results.violations > 0) return window.mySimulation.t('hint_ips_violation');
            if (results.biasResult === 'biased') return window.mySimulation.t('hint_bias_detected');
            var maxAlloc = Math.max(
                state.decisions.allocEquityCL,
                state.decisions.allocEquityUS,
                state.decisions.allocFixedIncome,
                state.decisions.allocReits,
                state.decisions.allocCash
            );
            if (maxAlloc > 50) return window.mySimulation.t('hint_concentrated');
            return window.mySimulation.t('hint_diversified');
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var returns = history.map(function(r) { return r.results ? r.results.quarterlyReturn : 0; });
            var cumReturn = returns.reduce(function(prod, r) {
                return prod * (1 + r / 100);
            }, 1) - 1;
            cumReturn = Math.round(cumReturn * 10000) / 100;

            var lastRecord = history[history.length - 1];
            var sharpe = lastRecord.results ? lastRecord.results.sharpeRatio : 0;
            var biasScore = lastRecord.results ? lastRecord.results.biasScore : 0;

            var biasedCount = 0;
            history.forEach(function(r) {
                if (r.results && r.results.biasResult === 'biased') biasedCount++;
            });

            var performanceKey = 'perf_beginner';
            if (sharpe >= 0.4 && cumReturn > 2) performanceKey = 'perf_good';
            if (sharpe >= 0.75 && cumReturn > 4) performanceKey = 'perf_excellent';
            var performance = this._t(performanceKey);

            var insights = [];
            if (sharpe >= 0.75) { insights.push(this._t('ins_sharpe_high')); }
            else if (sharpe >= 0.4) { insights.push(this._t('ins_sharpe_mid')); }
            else { insights.push(this._t('ins_sharpe_low')); }

            if (biasScore >= 85) { insights.push(this._t('ins_bias_high')); }
            else if (biasScore >= 55) { insights.push(this._t('ins_bias_mid')); }
            else { insights.push(this._t('ins_bias_low')); }

            if (biasedCount > 0) {
                insights.push(this._t('ins_bias_triggers').replace('{n}', biasedCount));
            }

            return {
                cumulativeReturn: cumReturn,
                sharpeRatio: sharpe,
                biasScore: biasScore,
                biasedDecisions: biasedCount,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        getPresets() { return null; }

        _t(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; }

        getTranslations() {
            return {
                en: {
                    title:                 `La Sala de Operaciones`,
                    subtitle:              `Fondo Privado Cóndor — Santiago de Chile`,
                    period_label:          `Quarter`,
                    period_of:             `of`,
                    portfolio_value_label: `Portfolio Value`,
                    quarterly_return_label:`Quarterly Return`,
                    cumulative_return_label:`Cumulative Return`,
                    sharpe_label:          `Sharpe Ratio`,
                    bias_score_label:      `Bias Score`,
                    ips_label:             `IPS Violations`,
                    briefing_heading:      `Market Briefing`,
                    bias_heading:          `Behavioral Decision`,
                    bias_choose:           `-- Select your response --`,
                    decisions_heading:     `Asset Allocation`,
                    allocation_hint:       `Allocate your portfolio across 5 asset classes (must total 100%)`,
                    alloc_equity_cl:       `Chilean Equities (%)`,
                    alloc_equity_us:       `US Equities (%)`,
                    alloc_fixed_income:    `Chilean Fixed Income (%)`,
                    alloc_reits:           `Real Assets / REITs (%)`,
                    alloc_cash:            `Cash / Money Market (%)`,
                    equity_cl_detail:      `IPSA portfolio — Beta 1.0 — Exp. Return 12.4%`,
                    equity_us_detail:      `S&P 500 ETF (CLP-hedged) — Beta 0.75 — Exp. Return 10.8%`,
                    fixed_income_detail:   `BCP 10-Year Bond Fund — Beta -0.12 — Exp. Return 5.8%`,
                    reits_detail:          `Fondo Inmobiliario Andes — Beta 0.45 — Exp. Return 8.6%`,
                    cash_detail:           `180-Day Fixed Deposit — Beta 0.00 — Exp. Return 4.9%`,
                    total_label:           `Total:`,
                    submit_btn:            `Submit Quarter`,
                    undo_btn:              `Undo Last Quarter`,
                    warning_sum_100:       `Allocation must total exactly 100%`,
                    warning_bias_response: `Please respond to the behavioral decision prompt before submitting`,
                    warning_cash_min:      `IPS constraint: minimum 10% in Cash / Money Market`,
                    warning_clp_min:       `IPS constraint: minimum 50% in CLP-denominated assets`,
                    hint_ips_violation:    `Warning: Your allocation violates IPS constraints. Review cash minimums and CLP requirements.`,
                    hint_bias_detected:    `A behavioral bias may have influenced your decision. Review the scenario rationally.`,
                    hint_concentrated:     `Your portfolio is highly concentrated. Diversification across uncorrelated assets reduces risk without sacrificing return.`,
                    hint_diversified:      `Good diversification. Monitor correlations as market conditions change across quarters.`,
                    col_return:            `Return (%)`,
                    col_value:             `Value (CLP M)`,
                    col_sharpe:            `Sharpe`,
                    col_bias:              `Bias Score`,
                    perf_beginner:`Beginner`, perf_good:`Good`, perf_excellent:`Excellent`,
                    ins_sharpe_high:`Outstanding risk-adjusted returns. Strong portfolio construction aligned with Modern Portfolio Theory.`,
                    ins_sharpe_mid:`Solid risk management. Consider further diversification with negatively correlated assets for higher Sharpe.`,
                    ins_sharpe_low:`Review asset allocation. Diversification across uncorrelated assets (fixed income vs equities) improves risk-adjusted returns.`,
                    ins_bias_high:`Excellent behavioral discipline. Few cognitive biases influenced your investment decisions.`,
                    ins_bias_mid:`Some behavioral biases affected judgment. Review anchoring, herding, and overconfidence triggers.`,
                    ins_bias_low:`Behavioral biases significantly impacted portfolio. Study Kahneman and Tversky on loss aversion and heuristic biases.`,
                    ins_bias_triggers:`Bias triggers activated: {n} of 3. Financial cost of each bias compounds across quarters.`,
                    chart_portfolio_label:`Portfolio (CLP M)`, chart_benchmark_label:`Benchmark IPSA+3% (CLP M)`, chart_title:`Portfolio vs. Benchmark (CLP M)`,
                    r1_briefing:           `Welcome to Fondo Privado Cóndor. You manage CLP 4,800M for 12 high-net-worth clients in Santiago de Chile.<br><br><strong>Investment Policy Statement (IPS):</strong><br>• Target return: 9.5% annual minimum<br>• Maximum drawdown: −15% in any single quarter<br>• Minimum cash: 10% at all times<br>• CLP-denominated assets: minimum 50%<br><br><strong>Key Correlations:</strong> Chilean Fixed Income is negatively correlated with equities (ρ = −0.15), making it a natural portfolio hedge. US Equities correlate at 0.72 with Chilean Equities — partial diversification only.<br><br>The Chilean economy is stable. IPSA at 6,200 points. Copper at USD 4.10/lb. Banco Central rate: 5.8%. Construct your initial portfolio.`,
                    r1_bias_prompt:        `Senior analyst Rodrigo Alarcón shares before your analysis: <em>"TECNOLOGIACL was trading at CLP 12,500 per share during the tech boom last year. Current price: CLP 8,200. The business fundamentals remain solid."</em><br><br>How does this information affect your allocation?`,
                    r1_bias_optA:          `The stock appears undervalued at CLP 8,200 vs. CLP 12,500 — increase Chilean equity allocation`,
